"""Result ORM Model representing output artifact data generated by task executions."""

from typing import TYPE_CHECKING
from sqlalchemy import ForeignKey, JSON, String
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.database.base import Base, TimestampMixin, UUIDMixin

if TYPE_CHECKING:
    from app.models.goal import Goal
    from app.models.task import Task


class Result(Base, UUIDMixin, TimestampMixin):
    """Represents output data generated by task execution or aggregated goal output."""

    __tablename__ = "results"

    goal_id: Mapped[str] = mapped_column(String(36), ForeignKey("goals.id", ondelete="CASCADE"), nullable=False, index=True)
    task_id: Mapped[str] = mapped_column(String(36), ForeignKey("tasks.id", ondelete="CASCADE"), nullable=False, index=True)
    output_data: Mapped[dict] = mapped_column(JSON, nullable=False)

    # Relationships
    goal: Mapped["Goal"] = relationship("Goal", back_populates="results")
    task: Mapped["Task"] = relationship("Task", back_populates="results")
